+// API keys and roles. A key belongs to one role; each role may do what the
+// roles below it may do: viewer reads, cook also does kitchen work (cook,
+// waste, temperatures, stock-take counts), manager does everything.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+/** The least role allowed to do each action. */
+const NEEDS = Object.freeze({ read: "viewer", kitchen: "cook", manage: "manager" });
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record matching `token`, or null. */
+export function findKey(store, token) {
+  if (typeof token !== "string" || token === "") return null;
+  const want = digest(token);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), want) && ROLES.includes(k.role)) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` may do `action` ("read", "kitchen" or "manage"). */
+export function allows(role, action) {
+  const need = NEEDS[action];
+  return need !== undefined && ROLES.indexOf(role) >= ROLES.indexOf(need) && ROLES.includes(role);
+}
