+// The audit log: one entry per request that changes data, written by the
+// caller after the request was answered. Entries are never edited or deleted.
+
+/** Appends an audit entry { at, key, method, path, status }; returns it. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return (store.data.audit ?? []).slice().reverse();
+}
