+// Which action each route needs (see src/domain/access.js for the roles).
+// Reads need "read" unless listed; every other method needs "manage" unless
+// listed.
+const ACTIONS = Object.freeze({
+  "GET /audit": "manage",
+  "POST /recipes/:id/cook": "kitchen",
+  "POST /batches/:id/waste": "kitchen",
+  "POST /temperatures": "kitchen",
+  "POST /stocktakes/:id/counts": "kitchen",
+});
+
+/** True for methods that only read. */
+export const isRead = (method) => method === "GET" || method === "HEAD";
+
+/** The action a route ("METHOD /pattern") needs. */
+export function actionFor(method, route) {
+  return ACTIONS[route] ?? (isRead(method) ? "read" : "manage");
+}
+
+/** The bearer token from an Authorization header, or null. */
+export function bearerToken(headers) {
+  const name = Object.keys(headers ?? {}).find((h) => h.toLowerCase() === "authorization");
+  const value = name === undefined ? undefined : headers[name];
+  const m = typeof value === "string" ? /^Bearer\s+(\S+)\s*$/i.exec(value) : null;
+  return m ? m[1] : null;
+}
