diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..f15f4d9
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,56 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer, KEYS } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { handle, store } = app();
+  const none = await handle({ path: "/items", headers: {} });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await handle({ method: "POST", path: "/jobs/nightly", headers: bearer("nope") });
+  assert.equal(bad.status, 401);
+  const basic = await handle({ path: "/items", headers: { authorization: `Basic ${KEYS.manager}` } });
+  assert.equal(basic.status, 401);
+  assert.equal((store.data.audit ?? []).length, 0);
+});
+
+test("viewers only read", async () => {
+  const { handle } = app(undefined, { key: KEYS.viewer });
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks do kitchen work but not management", async () => {
+  const { handle } = app(undefined, { key: KEYS.cook });
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5, reason: "spill" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks enter stock-take counts a manager started", async () => {
+  const { handle, store } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const cook = app(store, { key: KEYS.cook }).handle;
+  assert.equal((await cook({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await cook({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+});
+
+test("changes are audited and managers read the audit newest first", async () => {
+  const { handle, store } = app();
+  const cook = app(store, { key: KEYS.cook }).handle;
+  await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await cook({ method: "POST", path: "/jobs/nightly" });
+  await handle({ path: "/items" });
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body, [
+    { at: "2026-10-28T10:00:00.000Z", key: "dev cook", method: "POST", path: "/jobs/nightly", status: 403 },
+    { at: "2026-10-28T10:00:00.000Z", key: "dev cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+});
